function rebuildLine(people: number[][]): number[][] {
  const n = people.length;
  const sorted = [...people].sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const line: (number[] | null)[] = new Array(n).fill(null);
  for (const p of sorted) {
    let free = p[1];
    for (let i = 0; i < n; i++) {
      if (line[i] !== null) continue;
      if (free === 0) { line[i] = p; break; }
      free--;
    }
  }
  return line as number[][];
}

