class Solution:
    def rebuildLine(self, people: List[List[int]]) -> List[List[int]]:
        n = len(people)
        line = [None] * n
        for h, k in sorted(people, key=lambda p: (p[0], -p[1])):
            free = k
            for i in range(n):
                if line[i] is not None:
                    continue
                if free == 0:
                    line[i] = [h, k]
                    break
                free -= 1
        return line

