function rebuildLine(people: number[][]): number[][] {
  const sorted = [...people].sort((a, b) => b[0] - a[0] || a[1] - b[1]);
  const line: number[][] = [];
  for (const p of sorted) line.splice(p[1], 0, p);
  return line;
}

